from __future__ import annotations
from typing import Sequence, Optional
import numpy as np
from scipy.optimize import minimize


def nearest_point_in_hull(points: Sequence[np.ndarray]) -> tuple[np.ndarray, np.ndarray]:
    pts = np.asarray(points, dtype=float)
    n = pts.shape[0]

    def obj(w: np.ndarray) -> float:
        return float(np.dot(pts.T @ w, pts.T @ w))

    cons = ({"type": "eq", "fun": lambda w: float(np.sum(w) - 1.0)},)
    res = minimize(obj, np.full(n, 1.0 / n), method="SLSQP",
                   bounds=[(0.0, None)] * n, constraints=cons)
    w = np.clip(res.x, 0.0, None)
    w = w / np.sum(w)
    return pts.T @ w, w


def colorful_descent(colors: Sequence[Sequence[np.ndarray]],
                     tol: float = 1e-7, max_iter: int = 1000
                     ) -> Optional[list[np.ndarray]]:
    """Construct a colorful transversal whose convex hull contains the origin."""
    d = int(np.asarray(colors[0][0]).shape[0])
    if len(colors) < d + 1:
        return None
    trans = [np.asarray(c[0], dtype=float) for c in colors]
    for _ in range(max_iter):
        p, w = nearest_point_in_hull(trans)
        if float(np.linalg.norm(p)) < tol:
            return trans
        p_sq = float(np.dot(p, p))
        used = {i for i, wi in enumerate(w) if wi > 1e-9}
        for j in range(len(colors)):
            if j in used:
                continue
            for y in colors[j]:
                y = np.asarray(y, dtype=float)
                if float(np.dot(p, y)) < p_sq - 1e-12:
                    trans[j] = y
                    break
    return trans

